// ProjectIdentity answers one candidate row's owner-issued identity: the
// canonical digest, and the frame it was issued under. A content identity is
// issued under no frame and answers zero; a semantic axis answers the frame
// its own owner minted it at, which is what reconstitutes the key.
func (owner *RelationOwner) ProjectIdentity(relationOrdinal, projectionOrdinal, candidateOrdinal uint32) (identity.ContentID, uint64, bool) {
	if owner == nil || owner.schema == nil {
		return identity.ContentID{}, 0, false
	}
	switch relationOrdinal {
	case 24:
		switch projectionOrdinal {
		case 31:
			candidate, candidateOK := owner.schema.RuntimeKindCallAt(int(candidateOrdinal))
			if !candidateOK {
				return identity.ContentID{}, 0, false
			}
			first, second, projectionOK := candidate.CallOccurrence()
			if !projectionOK {
				return identity.ContentID{}, 0, false
			}
			_ = first
			projected := second
			return projected, 0, true
		default:
			return identity.ContentID{}, 0, false
		}
	default:
		return identity.ContentID{}, 0, false
	}
}

// materializeSourceColumns seals each owner-issued source fact column once.
func (owner *RelationOwner) materializeSourceColumns() bool {
	if owner == nil || owner.schema == nil {
		return false
	}
	count6 := owner.schema.SourceSeedCount()
	if count6 < 0 {
		return false
	}
	facts6 := make([]Value, count6)
	outcomes6 := make([]structure.ReductionOutcome, count6)
	for index := 0; index < count6; index++ {
		candidate, candidateOK := owner.schema.SourceSeedAt(index)
		if !candidateOK {
			return false
		}
		fact, outcome := SourceFact(candidate)
		if outcome == structure.Refuse {
			return false
		}
		facts6[index] = fact
		outcomes6[index] = outcome
	}
	column6, column6OK := memberrelation.NewSourceColumn(facts6, outcomes6)
	if !column6OK {
		return false
	}
	owner.sourceColumn6 = column6
	count7 := owner.schema.GlobalBootstrapResultCount()
	if count7 < 0 {
		return false
	}
	facts7 := make([]Value, count7)
	outcomes7 := make([]structure.ReductionOutcome, count7)
	for index := 0; index < count7; index++ {
		candidate, candidateOK := owner.schema.GlobalBootstrapResultAt(index)
		if !candidateOK {
			return false
		}
		fact, outcome := GlobalBootstrapFact(candidate)
		if outcome == structure.Refuse {
			return false
		}
		facts7[index] = fact
		outcomes7[index] = outcome
	}
	column7, column7OK := memberrelation.NewSourceColumn(facts7, outcomes7)
	if !column7OK {
		return false
	}
	owner.sourceColumn7 = column7
	return true
}

// SourceFactColumn returns the immutable typed source fact column for one relation.
// RelationCount is the sealed relation-ordinal extent. It preserves absent
// materializations separately from a valid empty source column.
func (*RelationOwner) RelationCount() int { return 35 }

func (owner *RelationOwner) SourceFactColumn(relationOrdinal uint32) (memberrelation.SourceColumn[Value], bool) {
	if owner == nil || owner.schema == nil {
		return memberrelation.SourceColumn[Value]{}, false
	}
	switch relationOrdinal {
	case 6:
		return owner.sourceColumn6, true
	case 7:
		return owner.sourceColumn7, true
	default:
		return memberrelation.SourceColumn[Value]{}, false
	}
}
